export function countTodos(items) {
  const completed = items.filter(item => item.completed).length;
  return {
    total: items.length,
    completed,
    active: items.length - completed,
  };
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { countTodos } from '../model.js';
test('統計正確且不修改原始項目', () => {
  const items = [
    { id: 'a', title: '買牛奶', completed: true },
    { id: 'b', title: '整理桌面', completed: false },
  ];
  const before = structuredClone(items);
  assert.deepEqual(countTodos(items), { total: 2, completed: 1, active: 1 });
  assert.deepEqual(items, before);
  assert.deepEqual(countTodos([]), { total: 0, completed: 0, active: 0 });
});
